// istIT und userEmail kommen ausschliesslich aus dem Parent-Kontext, nie aus
// dem Modell. Ab 08/2026 gilt das auch fuer originalFrage: der Agent formuliert
// suchtext frei um - aus "Insgesamt offen?" wurde "alle offenen Vorgaenge von
// Sebastian" (Beleg: Lauf 102546). Nur die durchgereichte Originalfrage ist als
// Absichtsquelle belastbar. suchtext bleibt Rueckfall, falls das Feld leer ist.
const inp = $input.first().json ?? {};
const istIT = inp.istIT === true || String(inp.istIT).toLowerCase() === 'true';
const userEmail = String(inp.userEmail ?? '').trim().toLowerCase();
const suchtext = String(inp.suchtext ?? '').trim().slice(0, 300);
const originalFrage = String(inp.originalFrage ?? '').trim().slice(0, 500);
const topN = Math.min(Math.max(Number(inp.topN ?? 5) || 5, 1), 10);
const frage = originalFrage || suchtext;

const entumlauten = s => String(s)
  .replace(/\u00e4/g, 'ae').replace(/\u00f6/g, 'oe').replace(/\u00fc/g, 'ue').replace(/\u00df/g, 'ss');
const ql = entumlauten(frage.toLowerCase());

// Ab hier nur noch die Rueckfallebene. Sie greift, wenn das Modell in
// 'Absicht auswerten' kein gueltiges JSON liefert.
const keyTreffer = ql.match(/ssd[\s-]?(\d{2,6})/i);
const ticketKey = keyTreffer ? 'SSD-' + keyTreffer[1] : '';

const stopwords = ['wie','was','wer','wo','wann','warum','ist','sind','kann','koennen','ich','du','wir','ein','eine','der','die','das','und','oder','fuer','mit','von','zum','zur','den','dem','des','beim','vom','auf','bei','nach','ueber','unter','nicht','kein','keine','mein','meine','meinen','bitte','hilfe','brauche','moechte','frage','habe','hat','gibt','einen','ticket','tickets','offene','offen','offenen','zeig','zeige','mir','hast','welche','alle','liste','infos','info','information','informationen','status','jira','vorgang','vorgaenge','anfrage','suche','finde','aktuell','aktuelle','aktuellen','derzeit','noch','etwas','sowie','laufende','laufenden','unerledigt','unerledigte','insgesamt','gesamt'];

const namensTeile = (userEmail.split('@')[0] || '')
  .split(/[._+-]+/).map(t => entumlauten(t.trim())).filter(t => t.length > 2);
const nameImText = namensTeile.some(t => new RegExp('\\b' + t + '\\b').test(ql));

const rohWoerter = frage.toLowerCase()
  .replace(/ssd[\s-]?\d{2,6}/gi, ' ')
  .split(/[^\p{L}\p{N}.]+/u).map(w => w.trim()).filter(Boolean);

const begriffe = [...new Set(rohWoerter
  .filter(w => w.length > 2)
  .filter(w => !stopwords.includes(entumlauten(w)))
  .filter(w => !namensTeile.includes(entumlauten(w))))].slice(0, 4);

const willOffen = /\b(offen|offene|offenen|unerledigt|unerledigte|aktiv|laufend|laufende|laufenden|open)\b/.test(ql);
const willZu = /\b(geschlossen|erledigt|abgeschlossen|closed|fertig)\b/.test(ql);
const eigenWunsch = /\b(mein|meine|meinen|meiner|meinem|ich|mir|mich|eigene|eigenen)\b/.test(ql) || nameImText;

const heuristik = {
  ticketKey,
  personBezug: eigenWunsch ? 'selbst' : 'keiner',
  personName: '',
  status: willOffen ? 'offen' : (willZu ? 'erledigt' : 'egal'),
  bereich: 'ssd',
  zeitraum: null,
  begriffe,
  sortierung: 'updated'
};

const anzeigeName = namensTeile.map(t => t.charAt(0).toUpperCase() + t.slice(1)).join(' ');

const systemPrompt = [
  'Du zerlegst eine Support-Frage in eine strukturierte Suchabsicht fuer Jira.',
  'Antworte ausschliesslich mit einem JSON-Objekt, ohne Markdown und ohne Erklaerung.',
  '',
  'Felder:',
  '- ticketKey: Schluessel wie "SSD-1234", sonst "".',
  '- personBezug: "selbst" bei Fragen nach eigenen Vorgaengen. "andere" bei einer namentlich genannten anderen Person. "keiner" beim Gesamtbestand oder einem Sachthema.',
  '- personName: nur bei "andere" der Name, sonst "".',
  '- status: "offen", "erledigt" oder "egal".',
  '- bereich: "ssd" fuer das Support-Projekt. "jira_gesamt" nur wenn ausdruecklich nach allen Jira-Projekten oder allen Vorgaengen ueber den Support hinaus gefragt wird.',
  '- zeitraum: {"feld":"created"|"updated","tage":N} bei Zeitangaben, sonst null.',
  '- begriffe: bis zu vier Sachbegriffe fuer die Volltextsuche. Keine Personennamen, keine Statuswoerter, keine Fuellwoerter. Bei einer reinen Bestands- oder Statusfrage ein leeres Array.',
  '- sortierung: "updated", "created" oder "prioritaet".',
  '',
  'Beispiele:',
  '"Meine offenen Vorgaenge?" -> {"ticketKey":"","personBezug":"selbst","personName":"","status":"offen","bereich":"ssd","zeitraum":null,"begriffe":[],"sortierung":"updated"}',
  '"Insgesamt offen?" -> {"ticketKey":"","personBezug":"keiner","personName":"","status":"offen","bereich":"ssd","zeitraum":null,"begriffe":[],"sortierung":"updated"}',
  '"Welche Tickets habe ich diese Woche gemeldet?" -> {"ticketKey":"","personBezug":"selbst","personName":"","status":"egal","bereich":"ssd","zeitraum":{"feld":"created","tage":7},"begriffe":[],"sortierung":"created"}',
  '"Gibt es offene Tickets zu d.velop?" -> {"ticketKey":"","personBezug":"keiner","personName":"","status":"offen","bereich":"ssd","zeitraum":null,"begriffe":["d.velop"],"sortierung":"updated"}',
  '"Status von SSD-8698?" -> {"ticketKey":"SSD-8698","personBezug":"keiner","personName":"","status":"egal","bereich":"ssd","zeitraum":null,"begriffe":[],"sortierung":"updated"}',
  '"Welche Vorgaenge hat Bernd Engelen offen?" -> {"ticketKey":"","personBezug":"andere","personName":"Bernd Engelen","status":"offen","bereich":"ssd","zeitraum":null,"begriffe":[],"sortierung":"updated"}'
].join('\n');

const frageFuerLLM = 'Anfragende Person: ' + (anzeigeName || userEmail) + '\nFrage: ' + frage;

return [{ json: { istIT, userEmail, topN, suchtext, originalFrage, frage, heuristik, systemPrompt, frageFuerLLM } }];

// Die JQL wird ausschliesslich hier gebaut, aus geprueften Absichtsfeldern.
// Das Modell liefert nie eine Klausel und nie eine accountId.
const ctl = $('Adresse festlegen').first().json ?? {};
const a = ctl.absicht ?? {};
const istIT = ctl.istIT === true;
const kandidaten = $input.all().map(i => i.json).filter(u => u && u.accountId);

// Kontoaufloesung. Ist die Adresse in Jira verborgen (DSGVO), zaehlt nur ein
// eindeutiger Einzeltreffer. Mehrdeutig => kein Konto.
const gesucht = String(ctl.emailFuerSuche || '').toLowerCase();
const perMail = kandidaten.find(u => String(u.emailAddress || '').toLowerCase() === gesucht);
const user = perMail || (kandidaten.length === 1 ? kandidaten[0] : null);
const accountId = user ? String(user.accountId || '').replace(/[^\w:-]/g, '') : '';

const esc = s => String(s).replace(/[^\p{L}\p{N} _.-]/gu, '').trim();
const teile = [];
let gueltig = true;
let hinweis = '';
let gateAngewandt = false;

// Bereich: der gesamte Jira-Bestand ist ausschliesslich fuer IT erreichbar.
// Fachbereich bleibt unter jeder Formulierung auf SSD.
const bereich = (istIT && a.bereich === 'jira_gesamt') ? 'jira_gesamt' : 'ssd';
if (bereich === 'ssd') teile.push('project = SSD');

// ENTSCHEIDUNG 08/2026: Teilnehmer ("Request participants", in JSM die
// CC-Rolle) gehoeren ins Gate. Jira selbst gewaehrt Teilnehmern Leserecht auf
// den Vorgang - der Agent war bisher strenger als das System dahinter und
// verschwieg Vorgaenge, die im Portal sichtbar sind. Gemessen an einem Konto:
// 75 Vorgaenge als Teilnehmer, davon 60 weder gemeldet noch bearbeitet noch
// angelegt. Feldname gegen SSD verifiziert (JQL "Request participants",
// REST-Feld customfield_10032, beidseitige Gegenprobe).
const gate = accountId
  ? '(reporter = "' + accountId + '" OR assignee = "' + accountId + '" OR creator = "' + accountId + '" OR "Request participants" = "' + accountId + '")'
  : '';

// Fail closed: ohne aufgeloestes Konto wird kein Personenbezug geraten.
if (!istIT) {
  if (!gate) {
    gueltig = false;
    hinweis = 'Der Ticketzugriff konnte nicht geprueft werden, weil das Jira-Konto der Person nicht eindeutig zugeordnet werden konnte.';
  } else {
    teile.push(gate);
    gateAngewandt = true;
  }
} else if (a.personBezug === 'selbst' || a.personBezug === 'andere') {
  if (gate) {
    teile.push(gate);
    gateAngewandt = true;
  } else {
    gueltig = false;
    hinweis = a.personBezug === 'andere'
      ? 'Die genannte Person konnte in Jira nicht eindeutig zugeordnet werden.'
      : 'Das eigene Jira-Konto konnte nicht eindeutig zugeordnet werden.';
  }
}

// Eine Rueckfrage schlaegt jede andere Meldung. Sie entsteht nur dort, wo ohne
// Nachfrage strukturell falsch geantwortet wuerde - nicht bei blosser Unschaerfe.
const rueckfrage = String(ctl.rueckfrage || '');
if (rueckfrage) {
  gueltig = false;
  hinweis = rueckfrage;
}

if (a.ticketKey) {
  teile.push('key = ' + a.ticketKey);
} else {
  const bg = (Array.isArray(a.begriffe) ? a.begriffe : []).map(esc).filter(b => b.length > 2);
  if (bg.length) teile.push('(' + bg.map(b => 'text ~ "' + b + '"').join(' OR ') + ')');
}

if (a.status === 'offen') teile.push('statusCategory != Done');
else if (a.status === 'erledigt') teile.push('statusCategory = Done');

if (a.zeitraum && a.zeitraum.feld && a.zeitraum.tage) {
  teile.push(a.zeitraum.feld + ' >= -' + Number(a.zeitraum.tage) + 'd');
}

const sortFeld = a.sortierung === 'created' ? 'created' : (a.sortierung === 'prioritaet' ? 'priority' : 'updated');
const basis = teile.length ? teile.join(' AND ') : 'created >= -3650d';

// Ungueltig => syntaktisch korrekte Abfrage ohne Treffer, kein Bypass.
const jql = gueltig
  ? basis + ' ORDER BY ' + sortFeld + ' DESC'
  : 'project = SSD AND created > "2999/01/01"';

// Bestandsfrage: kein Volltextfilter und kein Schluessel, also will die Person
// die vollstaendige Liste sehen und nicht die Top-N einer Relevanzsortierung.
const bestandsfrage = !a.ticketKey && !(Array.isArray(a.begriffe) && a.begriffe.length);

return [{ json: {
  ...ctl,
  jql,
  gueltig,
  accountId,
  gateAngewandt,
  bereich,
  bestandsfrage,
  rueckfrageNoetig: Boolean(rueckfrage),
  ticketKey: a.ticketKey || '',
  begriffe: Array.isArray(a.begriffe) ? a.begriffe : [],
  hinweis
} }];

const ctl = $('JQL bauen').first().json ?? {};
const a = ctl.absicht ?? {};
const roh = $input.all().map(i => i.json).filter(t => t && t.key && t.fields);
const accountId = String(ctl.accountId || '');
const istIT = ctl.istIT === true;

// Muss zur limit-Einstellung in 'Jira abfragen' passen: Bestandsfragen holen
// 300 Vorgaenge, alles andere 20. Die grosse Menge kostet nur Laufzeit im
// Workflow - der Agent sieht nie mehr als 20 Tickets.
const ABFRAGE_LIMIT = ctl.bestandsfrage ? 300 : 20;

// Teilnehmerfeld ("Request participants"). Die JQL kennt den Klarnamen, die
// REST-Antwort nur die Feld-ID. Gegen SSD verifiziert 08/2026.
const TEILNEHMER_FELD = 'customfield_10032';
const teilnehmerListe = f => {
  const v = f ? f[TEILNEHMER_FELD] : null;
  return Array.isArray(v) ? v.filter(p => p && p.accountId) : [];
};

// FIX 08/2026 (Beleg: Lauf 102704): Die Rollenangabe war aus Sicht der
// anfragenden Person formuliert ("in Bearbeitung durch dich"). Bei einer
// IT-Abfrage ueber eine andere Person - dort personBezug='andere', Konto
// Marcel Commes - bezieht sie sich aber auf die abgefragte Person. Der Agent
// haette der IT gemeldet, sie selbst bearbeite einen fremden Vorgang. Deshalb
// sind die Werte jetzt personenunabhaengig; wer gemeint ist, steht in
// rolleGiltFuer.
const rollenVon = (f, konto) => {
  if (!konto) return [];
  const ist = p => p && String(p.accountId || '') === konto;
  const r = [];
  if (ist(f.reporter)) r.push('gemeldet');
  if (ist(f.assignee)) r.push('in Bearbeitung');
  if (ist(f.creator) && !ist(f.reporter)) r.push('angelegt');
  if (teilnehmerListe(f).some(ist)) r.push('Teilnehmer');
  return r;
};

const fremdabfrage = a.personBezug === 'andere';
const rolleGiltFuer = fremdabfrage
  ? (a.personName || 'die abgefragte Person')
  : 'die anfragende Person';

// Zweite Sperre nach der JQL-Klausel. Kein Fallback auf fremde Tickets.
// Muss dieselben vier Rollen kennen wie die JQL, sonst wirft sie genau die
// Vorgaenge wieder raus, die das erweiterte Gate hereingelassen hat.
const erlaubt = istIT ? roh : roh.filter(t => {
  if (!accountId) return false;
  return rollenVon(t.fields || {}, accountId).length > 0;
});

// FIX 08/2026: Der Agent hat die Laenge der zurueckgegebenen Liste als
// Bestandszahl ausgegeben - "insgesamt 20 offene Tickets", tatsaechlich 43 in
// SSD und 464 im gesamten Jira (Beleg: Lauf 102567). trefferAnzahl ist die
// Anzahl der genannten Vorgaenge, gesamtAnzahl der Bestand. Ist das
// Abfragelimit erreicht, ist der Bestand nur eine Untergrenze.
const gesamtAnzahl = erlaubt.length;
const gesamtAnzahlExakt = roh.length < ABFRAGE_LIMIT;

const sauber = d => String(d || '')
  .replace(/\{code(:[^}]*)?\}/gi, ' ').replace(/\{noformat\}/gi, ' ')
  .replace(/\{quote\}/gi, ' ').replace(/\{color[^}]*\}/gi, '').replace(/\{\{|\}\}/g, '')
  .replace(/\{panel[^}]*\}/gi, ' ')
  .replace(/(^|[\s.])h[1-6]\.\s+/gi, '$1')
  .replace(/[*_+]{1,2}([^*_+\n]+)[*_+]{1,2}/g, '$1')
  .replace(/\|+/g, ' ').replace(/\s+/g, ' ').trim();

// Bei Stichwortsuchen zaehlt zusaetzlich die Begriffsdeckung, damit nicht das
// juengste statt des passenden Tickets oben steht.
const begriffe = Array.isArray(ctl.begriffe) ? ctl.begriffe : [];
const bewertet = erlaubt.map((t, idx) => {
  const f = t.fields || {};
  const titel = String(f.summary || '');
  const text = sauber(f.description);
  let punkte = 0;
  for (const b of begriffe) {
    const bl = String(b).toLowerCase();
    if (titel.toLowerCase().includes(bl)) punkte += 3;
    if (text.toLowerCase().includes(bl)) punkte += 1;
  }
  return { t, f, titel, text, punkte, idx };
});

if (ctl.bestandsfrage) bewertet.sort((x, y) => x.idx - y.idx);
else bewertet.sort((x, y) => y.punkte - x.punkte || x.idx - y.idx);

const limit = ctl.bestandsfrage ? 20 : (Number(ctl.topN) || 5);

const tickets = bewertet.slice(0, limit).map(x => {
  const rollen = rollenVon(x.f, accountId);
  return {
    key: x.t.key,
    titel: x.titel,
    status: x.f.status?.name || '',
    prioritaet: x.f.priority?.name || '',
    bearbeiter: x.f.assignee?.displayName || 'nicht zugewiesen',
    gemeldetVon: x.f.reporter?.displayName || '',
    // Warum dieser Vorgang in der Liste steht. Neutral formuliert - auf wen
    // sich die Rolle bezieht, steht in rolleGiltFuer.
    rolle: rollen.join(', '),
    rolleGiltFuer,
    nurTeilnehmer: rollen.length === 1 && rollen[0] === 'Teilnehmer',
    aktualisiert: x.f.updated || '',
    beschreibung: x.text.slice(0, 600),
    url: 'https://rwg-r.atlassian.net/browse/' + x.t.key
  };
});

const hinweise = [];
if (ctl.hinweis) hinweise.push(String(ctl.hinweis));

if (tickets.length === 0 && !ctl.hinweis) {
  hinweise.push(istIT
    ? 'Keine passenden Vorgaenge gefunden.'
    : 'Zu dieser Anfrage sind keine Tickets vorhanden, die dieser Person gehoeren. Tickets anderer Personen werden nicht ausgegeben.');
}

if (tickets.length > 0) {
  if (!gesamtAnzahlExakt) {
    hinweise.push('Bestand: mindestens ' + gesamtAnzahl + ' Vorgaenge, die genaue Zahl steht nicht fest. Nur als Untergrenze nennen.');
  } else {
    hinweise.push('Bestand: genau ' + gesamtAnzahl + ' Vorgaenge. Diese Zahl nennen, wenn nach einer Anzahl gefragt wurde.');
  }
  if (gesamtAnzahl > tickets.length) {
    hinweise.push('Diese Antwort enthaelt nur ' + tickets.length + ' der ' + gesamtAnzahl + ' Vorgaenge, naemlich die zuletzt aktualisierten. Sage ausdruecklich, dass die Liste unvollstaendig ist. Behaupte nie, sie sei vollstaendig.');
  } else if (ctl.bestandsfrage) {
    hinweise.push('Die Liste ist vollstaendig. Alle Eintraege nennen, nicht nur den ersten.');
  }

  // Anweisung statt blosser Feststellung - im Werkzeugergebnis wirkt sie
  // zuverlaessiger als eine Regel im Systemprompt.
  const nurTeilnehmerZahl = tickets.filter(t => t.nurTeilnehmer).length;
  if (fremdabfrage) {
    hinweise.push('Das Feld rolle beschreibt die Rolle von ' + rolleGiltFuer + ', nicht die der anfragenden Person. Formuliere entsprechend, zum Beispiel "' + rolleGiltFuer + ' ist dort als Teilnehmer eingetragen". Sage niemals "du" ueber diese Rolle.');
  }
  if (nurTeilnehmerZahl > 0) {
    hinweise.push('Bei ' + nurTeilnehmerZahl + ' der genannten Vorgaenge lautet die Rolle nur "Teilnehmer" - der Vorgang wurde also weder gemeldet noch angelegt noch bearbeitet, sondern die Person wurde lediglich hinzugefuegt. Nenne bei jedem Vorgang kurz das Feld rolle, damit erkennbar bleibt, warum er in der Liste steht.');
  }
}

// eigentumBestaetigt gilt nur, wenn das Kontogate auf die anfragende Person
// selbst angewandt wurde - nicht bei einer Abfrage ueber eine andere Person.
const gateAngewandt = ctl.gateAngewandt === true;
const eigenerBezug = a.personBezug === 'selbst';

return [{ json: {
  trefferAnzahl: tickets.length,
  gesamtAnzahl,
  gesamtAnzahlExakt,
  tickets,
  hinweis: hinweise.join(' '),
  eigentumBestaetigt: gateAngewandt && eigenerBezug && tickets.length > 0,
  diagnose: {
    rohTreffer: roh.length,
    nachEigentumsfilter: erlaubt.length,
    nurTeilnehmer: tickets.filter(t => t.nurTeilnehmer).length,
    rolleGiltFuer,
    fremdabfrage,
    abfrageLimit: ABFRAGE_LIMIT,
    istIT,
    kontoAufgeloest: Boolean(accountId),
    gateAngewandt,
    bestandsfrage: ctl.bestandsfrage === true,
    bereich: ctl.bereich || 'ssd',
    absichtQuelle: ctl.absichtQuelle || '',
    absichtFehler: ctl.absichtFehler || '',
    personBezug: a.personBezug || '',
    personName: a.personName || '',
    personMail: ctl.personMail || '',
    status: a.status || '',
    zeitraum: a.zeitraum || null,
    ticketKey: ctl.ticketKey || null,
    begriffe,
    jql: ctl.jql || ''
  }
} }];

// Das Modell liefert ausschliesslich Absicht, niemals JQL. Jeder Wert wird
// gegen eine Whitelist geprueft; die Autorisierung entscheidet der Code.
const ctl = $('Anfrage pruefen').first().json ?? {};
const antwort = $input.first().json ?? {};

const erlaubtPerson = ['selbst','andere','keiner'];
const erlaubtStatus = ['offen','erledigt','egal'];
const erlaubtBereich = ['ssd','jira_gesamt'];
const erlaubtSort = ['updated','created','prioritaet'];

let absicht = null;
let quelle = 'heuristik';
let fehler = '';

try {
  const text = antwort?.choices?.[0]?.message?.content;
  if (text) {
    const p = JSON.parse(String(text));
    absicht = {
      ticketKey: /^SSD-\d{2,6}$/i.test(String(p.ticketKey || '')) ? String(p.ticketKey).toUpperCase() : '',
      personBezug: erlaubtPerson.includes(p.personBezug) ? p.personBezug : 'keiner',
      personName: String(p.personName || '').replace(/[^\p{L}\s.'-]/gu, '').trim().slice(0, 60),
      status: erlaubtStatus.includes(p.status) ? p.status : 'egal',
      bereich: erlaubtBereich.includes(p.bereich) ? p.bereich : 'ssd',
      zeitraum: (p.zeitraum && ['created','updated'].includes(p.zeitraum.feld) && Number(p.zeitraum.tage) > 0)
        ? { feld: p.zeitraum.feld, tage: Math.min(Math.round(Number(p.zeitraum.tage)), 730) }
        : null,
      begriffe: Array.isArray(p.begriffe)
        ? [...new Set(p.begriffe.map(b => String(b).trim()).filter(b => b.length > 2))].slice(0, 4)
        : [],
      sortierung: erlaubtSort.includes(p.sortierung) ? p.sortierung : 'updated'
    };
    quelle = 'llm';
  } else {
    fehler = 'keine Modellantwort';
  }
} catch (e) {
  fehler = String(e && e.message ? e.message : e).slice(0, 200);
}

if (!absicht) absicht = { ...(ctl.heuristik || {}) };

// Fachbereich: der Personenbezug ist nicht verhandelbar und der Bereich bleibt
// SSD. Damit kann keine Modellausgabe das Kontogate umgehen.
if (ctl.istIT !== true) {
  absicht.personBezug = 'selbst';
  absicht.personName = '';
  absicht.bereich = 'ssd';
}
if (absicht.personBezug !== 'andere') absicht.personName = '';

// Bei einer Anschlussfrage ("und wer bearbeitet das?") steht die Kennung nicht
// mehr in der Originalfrage, wohl aber im suchtext - dort hat der Agent den
// Bezug bereits aufgeloest. Ohne diesen Rueckgriff ging der Schluessel verloren
// und die JQL wurde zur Gesamtliste des Projekts (Beleg: Lauf 109485).
// Der Schluessel ist ein hartes Muster und keine Berechtigung: 'JQL bauen'
// ergaenzt das Kontogate unabhaengig davon per AND, fuer den Fachbereich
// ausnahmslos. Ein vom Modell erfundener Schluessel oeffnet daher nichts.
if (!absicht.ticketKey) {
  const ktr = String((ctl.frage || '') + ' ' + (ctl.suchtext || ''))
    .match(/ssd[\s-]?(\d{2,6})/i);
  if (ktr) absicht.ticketKey = 'SSD-' + ktr[1];
}

// Ein Ticketschluessel schlaegt jede Volltextsuche.
if (absicht.ticketKey) absicht.begriffe = [];

// FIX 08/2026: Die Kontosuche ueber den Klarnamen scheiterte, weil der
// Jira-displayName der Adresse folgt und nicht dem Namen - "Sebastian Linges"
// fand nichts, der Account heisst "sebastian.linges" (Beleg: Lauf 102557,
// gueltig=false). Geprueft an zehn Konten: die Adresse folgt durchgaengig
// vorname.nachname@rwg-r.de, Umlaute entumlautet, Bindestriche im Vornamen
// erhalten (vincent-hendrik.borresch@rwg-r.de). Deshalb wird der Name in eine
// Adresse uebersetzt statt als Freitext gesucht.
const entumlauten = s => String(s)
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss');

const nameZuMail = n => {
  const teile = entumlauten(String(n).toLowerCase().trim())
    .split(/\s+/).map(t => t.replace(/[^a-z0-9-]/g, '')).filter(Boolean);
  if (teile.length < 2) return '';
  const nachname = teile[teile.length - 1];
  const vorname = teile.slice(0, -1).join('-');
  return vorname + '.' + nachname + '@rwg-r.de';
};

let emailFuerSuche = ctl.userEmail || 'kein-treffer@invalid.local';
let personMail = '';
let rueckfrage = '';

if (absicht.personBezug === 'andere' && absicht.personName) {
  // FIX 08/2026 (Beleg: Lauf 102605): Bei einem blossen Vornamen ergaenzt das
  // Modell eigenmaechtig einen Nachnamen - aus "Was hat Sebastian offen?" wurde
  // "Sebastian Linges", also der Name der anfragenden Person aus dem Prompt.
  // Die Pruefung auf zwei Namensteile in nameZuMail greift dadurch nie, und der
  // Agent haette fremde Ticketlisten unter falschem Namen praesentiert.
  // Belastbar ist nur der Abgleich gegen den Fragetext: jedes Namensteil muss
  // dort wirklich stehen. Steht es nicht da, wird nicht geraten, sondern
  // zurueckgefragt.
  const frageNorm = entumlauten(String(ctl.frage || '').toLowerCase());
  const teile = entumlauten(absicht.personName.toLowerCase()).split(/\s+/).filter(Boolean);
  const wirklichGefragt = teile.length >= 2 && teile.every(t => frageNorm.includes(t));

  if (wirklichGefragt) {
    personMail = nameZuMail(absicht.personName);
    emailFuerSuche = personMail || 'kein-treffer@invalid.local';
  } else if (/\b(mein|meine|meinen|meiner|meinem|ich|mir|mich|eigene|eigenen)\b/.test(frageNorm)) {
    // Die Frage traegt einen klaren Selbstbezug ("von mir", "meine", "mein Todo"),
    // und der vom Modell genannte Name steht nicht vollstaendig im Fragetext.
    // Dann ist es keine Fremdabfrage, sondern eine Frage nach eigenen Vorgaengen.
    // Die Korrektur geht ausschliesslich von "andere" nach "selbst" und damit auf
    // die engere Sicht - fremde Vorgaenge werden dadurch nie zugaenglich.
    absicht.personBezug = 'selbst';
    absicht.personName = '';
    emailFuerSuche = ctl.userEmail || 'kein-treffer@invalid.local';
  } else {
    const genannt = String(absicht.personName).split(/\s+/)[0] || 'die genannte Person';
    rueckfrage = 'Rueckfrage stellen: Zu "' + genannt + '" gibt es keinen eindeutigen Treffer, weil nur ein Namensteil genannt wurde. Frage nach Vor- und Nachname, zum Beispiel "Was hat Stefan Kox offen?". Nenne keine Tickets und ergaenze den Namen nicht selbst.';
    absicht.personName = '';
    emailFuerSuche = 'kein-treffer@invalid.local';
  }
}

return [{ json: {
  istIT: ctl.istIT === true,
  userEmail: ctl.userEmail || '',
  topN: ctl.topN || 5,
  frage: ctl.frage || '',
  suchtext: ctl.suchtext || '',
  originalFrage: ctl.originalFrage || '',
  absicht,
  absichtQuelle: quelle,
  absichtFehler: fehler,
  personMail,
  rueckfrage,
  emailFuerSuche
} }];

// Exakte Adresse schlaegt konstruierte Adresse. 'Absicht auswerten' leitet die
// Mailadresse einer dritten Person aus dem Namen ab (vorname.nachname@rwg-r.de).
// Das ist eine Konvention und keine Auskunft: Akzente, Namenszusaetze und jede
// Abweichung vom Schema erzeugen eine Adresse, die es nicht gibt. Entra fuehrt
// den echten Namen samt verbindlicher Adresse, deshalb gilt der
// Verzeichnistreffer, wo es einen gibt.
//
// Der Block wirkt ausschliesslich bei personBezug 'andere'. Fuer den
// Fachbereich steht dieser Wert weiter oben hart auf 'selbst'; die
// Verzeichnissuche ist dort strukturell unerreichbar.
const ctl = $('Absicht auswerten').first().json ?? {};
const res = $input.first().json ?? {};
const a = ctl.absicht ?? {};

// Beide Seiten werden identisch normalisiert: Zerlegung in Grundzeichen, dann
// Wegwerfen aller Nicht-ASCII-Reste. Akzente und Umlaute fallen dabei auf
// beiden Seiten gleichermassen weg - aus "Andre" mit Akzent wird "andre", aus
// "Strauss" mit Eszett auf beiden Seiten "strau".
const norm = s => String(s ?? '').normalize('NFD').toLowerCase()
  .split('').filter(c => c.charCodeAt(0) < 128).join('')
  .replace(/[^a-z]/g, '');

const kandidaten = Array.isArray(res.value) ? res.value : [];
const teile = String(a.personName || '').trim().split(/\s+/).map(norm).filter(Boolean);
const nachGesucht = teile.length ? teile[teile.length - 1] : '';
const vorGesucht = teile.slice(0, -1).join('');

// Entra fuehrt den Anzeigenamen als "Nachname Vorname". Welcher Teil im
// Fragetext vorne stand, ist damit nicht verlaesslich. Geprueft wird deshalb
// gegen givenName und surname, und zwar in beiden Zuordnungen.
const treffer = (vorGesucht && nachGesucht)
  ? kandidaten.filter(u => {
      const gn = norm(u.givenName);
      const sn = norm(u.surname);
      return (gn === vorGesucht && sn === nachGesucht) || (gn === nachGesucht && sn === vorGesucht);
    })
  : [];

let entraStatus = 'nicht_gesucht';
let entraMail = '';

if (a.personBezug === 'andere' && a.personName) {
  if (treffer.length === 1) {
    entraMail = String(treffer[0].mail || treffer[0].userPrincipalName || '').trim().toLowerCase();
    entraStatus = entraMail ? 'eindeutig' : 'ohne_adresse';
  } else if (treffer.length > 1) {
    entraStatus = 'mehrdeutig';
  } else {
    entraStatus = 'kein_treffer';
  }
}

let emailFuerSuche = ctl.emailFuerSuche || 'kein-treffer@invalid.local';
let personMail = ctl.personMail || '';
let rueckfrage = ctl.rueckfrage || '';

if (entraStatus === 'eindeutig') {
  personMail = entraMail;
  emailFuerSuche = entraMail;
} else if (entraStatus === 'mehrdeutig' && !rueckfrage) {
  // Mehrere Personen tragen den Namen. Eine Auswahl waere hier ein Griff in
  // fremde Vorgaenge, deshalb wird gefragt statt gewaehlt.
  rueckfrage = 'Rueckfrage stellen: Zum genannten Namen gibt es mehrere Personen im Verzeichnis. Bitte um eine eindeutige Angabe, zum Beispiel die vollstaendige Mailadresse. Nenne keine Tickets und waehle nicht selbst aus.';
  personMail = '';
  emailFuerSuche = 'kein-treffer@invalid.local';
}

// kein_treffer und ohne_adresse: die konstruierte Adresse bleibt als Rueckfall
// bestehen. Traegt auch sie nicht, meldet 'JQL bauen' weiterhin gueltig = false
// und es wird nichts geraten.

return [{ json: {
  ...ctl,
  personMail,
  rueckfrage,
  emailFuerSuche,
  entraStatus,
  entraKandidaten: kandidaten.length
} }];
